// Procedural layers: motion described by what it IS, not by its keyframes.
//
// A walk is "these legs, this pattern, this stride" - writing it as keys means
// a dozen IK keys per leg that must line up in phase (the first hand-written
// horse walk took 13 keys and still had to be generated by a script). A layer
// is a function of time compiled on every frame and ADDED to whatever the
// keys say, so keys hold the base pose / the acting and layers hold the
// cycles:
//
//   gait       legs stepping in a pattern (walk, trot, pace, bound, gallop,
//              alternate/tripod, wave), feet planted by IK, in place or
//              travelling
//   wave       a travelling wave down a chain - slither, tail wag, tentacles
//   oscillate  a periodic swing of one control - wing flaps, breathing, nods
//   noise      smooth loop-safe fidget for idles
//   spring     follow-through: a chain lags behind the body and overshoots
//              (applied after everything else, frame by frame)
//
// Every layer may be limited to a window ("start", "end", "fade" seconds).
// Periodic layers take "cycles" per clip; on a looping clip a whole number of
// cycles is what makes the loop seamless, and normalizeLayers says so.

const TWO_PI = Math.PI * 2;
export const LAYER_TYPES = ['gait', 'wave', 'oscillate', 'noise', 'spring'];
export const GAIT_PATTERNS = ['auto', 'walk', 'trot', 'pace', 'bound', 'gallop', 'alternate', 'tripod', 'wave'];
const CONTROLS = ['forward', 'up', 'left', 'out', 'turn', 'pitch', 'roll', 'twist'];

const num = (v, fallback) => (Number.isFinite(Number(v)) ? Number(v) : fallback);
const asList = v => (Array.isArray(v) ? v : (v === undefined || v === null ? [] : [v])).map(String).filter(Boolean);

/** Validate and fill defaults. Returns { layers, errors, warnings }. */
export function normalizeLayers(raw, { duration, loop }) {
  const errors = [];
  const warnings = [];
  if (raw === undefined || raw === null) return { layers: [], errors, warnings };
  if (!Array.isArray(raw)) { errors.push('"layers" must be an array.'); return { layers: [], errors, warnings }; }
  const layers = [];
  raw.forEach((input, i) => {
    const where = `layers[${i}]`;
    if (!input || typeof input !== 'object') { errors.push(`${where} is not an object.`); return; }
    const type = String(input.type || '');
    if (!LAYER_TYPES.includes(type)) { errors.push(`${where}.type must be one of ${LAYER_TYPES.join(', ')}.`); return; }
    const base = {
      type,
      weight: num(input.weight, 1),
      start: Math.max(0, num(input.start, 0)),
      end: Math.min(duration, num(input.end, duration)),
      fade: Math.max(0, num(input.fade, 0))
    };
    if (base.end <= base.start) { errors.push(`${where}: "end" must be after "start".`); return; }
    const cyclesCheck = (cycles) => {
      if (loop && Math.abs(cycles - Math.round(cycles)) > 1e-6 && base.start === 0 && base.end === duration) {
        warnings.push(`${where}: ${cycles} cycles on a looping clip does not close the loop - use a whole number.`);
      }
    };
    if (type === 'gait') {
      const pattern = String(input.pattern || 'auto');
      if (!GAIT_PATTERNS.includes(pattern)) { errors.push(`${where}.pattern must be one of ${GAIT_PATTERNS.join(', ')}.`); return; }
      const travel = input.travel === 'forward' ? 'forward' : 'in_place';
      const layer = {
        ...base,
        legs: input.legs === undefined || input.legs === 'auto' ? 'auto' : asList(input.legs),
        pattern,
        phases: input.phases && typeof input.phases === 'object' ? Object.fromEntries(Object.entries(input.phases).map(([k, v]) => [k, num(v, 0)])) : null,
        cycles: Math.max(0.25, num(input.cycles, 1)),
        stride: input.stride === undefined ? null : num(input.stride, null),
        lift: input.lift === undefined ? null : num(input.lift, null),
        duty: input.duty === undefined ? null : Math.min(0.95, Math.max(0.2, num(input.duty, 0.6))),
        travel,
        bob: num(input.bob, 0),
        sway: num(input.sway, 0)
      };
      cyclesCheck(layer.cycles);
      if (travel === 'forward' && loop) warnings.push(`${where}: travel "forward" on a looping clip makes a ROOT-MOTION clip - the body advances and snaps back when it loops, which is what engines expect for root motion. Use "in_place" for a cycle that loops in place.`);
      layers.push(layer);
    } else if (type === 'wave') {
      const chains = asList(input.chain ?? input.chains);
      if (!chains.length) { errors.push(`${where}: "chain" (a chain label, or a list) is required.`); return; }
      const control = String(input.control || 'left');
      if (!CONTROLS.includes(control)) { errors.push(`${where}.control must be one of ${CONTROLS.join(', ')}.`); return; }
      const layer = {
        ...base,
        chains,
        control,
        amplitude: num(input.amplitude, 15),
        cycles: num(input.cycles, 1),
        waves: num(input.waves, 1),
        phase: num(input.phase, 0),
        falloff: ['even', 'tip', 'base'].includes(input.falloff) ? input.falloff : 'tip',
        direction: input.direction === 'tip_to_base' ? 'tip_to_base' : 'base_to_tip'
      };
      cyclesCheck(layer.cycles);
      layers.push(layer);
    } else if (type === 'oscillate') {
      const targets = asList(input.target ?? input.targets);
      if (!targets.length) { errors.push(`${where}: "target" (a pose target or a list) is required.`); return; }
      const control = String(input.control || 'up');
      if (!CONTROLS.includes(control) && control !== 'root.up' && !/^root\.(forward|up|left|turn|pitch|roll)$/.test(control)) {
        errors.push(`${where}.control must be one of ${CONTROLS.join(', ')} (or root.<control> with target "root").`);
        return;
      }
      const layer = {
        ...base,
        targets,
        control,
        amplitude: num(input.amplitude, 20),
        offset: num(input.offset, 0),
        cycles: num(input.cycles, 1),
        phase: num(input.phase, 0),
        shape: ['sine', 'flap', 'pulse'].includes(input.shape) ? input.shape : 'sine'
      };
      cyclesCheck(layer.cycles);
      layers.push(layer);
    } else if (type === 'noise') {
      const targets = asList(input.target ?? input.targets);
      if (!targets.length) { errors.push(`${where}: "target" is required.`); return; }
      const controls = asList(input.control ?? input.controls ?? ['turn', 'pitch']).filter(c => CONTROLS.includes(c));
      layers.push({
        ...base,
        targets,
        controls: controls.length ? controls : ['turn', 'pitch'],
        amplitude: num(input.amplitude, 4),
        speed: Math.max(1, Math.round(num(input.speed, 2))),
        seed: Math.round(num(input.seed, 1))
      });
    } else if (type === 'spring') {
      const chains = asList(input.chain ?? input.chains);
      if (!chains.length) { errors.push(`${where}: "chain" is required.`); return; }
      layers.push({
        ...base,
        chains,
        stiffness: Math.min(1, Math.max(0.02, num(input.stiffness, 0.25))),
        damping: Math.min(0.95, Math.max(0, num(input.damping, 0.3)))
      });
    }
  });
  return { layers, errors, warnings };
}

function envelope(layer, t) {
  if (t < layer.start - 1e-9 || t > layer.end + 1e-9) return 0;
  let w = layer.weight;
  // Fade only at an edge that is inside the clip - a layer running to the end
  // of a loop must not fade out at the seam.
  if (layer.fade > 0) {
    if (layer.start > 1e-9) w *= Math.min(1, (t - layer.start) / layer.fade);
    if (layer.end < layer.endOfClip - 1e-9) w *= Math.min(1, (layer.end - t) / layer.fade);
  }
  return Math.max(0, w);
}

function add(obj, key, control, value) {
  if (!value) return;
  const slot = key === null ? obj : (obj[key] = obj[key] || {});
  slot[control] = (slot[control] || 0) + value;
}

// ---- gait ------------------------------------------------------------------

/** Legs of a gait, ordered front to back, with side and length. */
export function gaitLegs(ctx, layer) {
  const { description } = ctx;
  let chains = description.chains.filter(c => c.kind === 'leg');
  if (layer.legs !== 'auto') {
    chains = layer.legs.map(label => description.chains.find(c => c.label === label)).filter(Boolean);
  }
  return chains
    .map(c => ({ label: c.label, side: c.side === 'left' ? 1 : c.side === 'right' ? -1 : 0, forward: c.base[0], length: c.length }))
    .sort((a, b) => b.forward - a.forward);
}

/**
 * Phase (0..1 of the cycle) at which each leg STARTS its stance, plus the
 * default duty factor (fraction of the cycle a foot is on the ground).
 */
export function gaitPhases(legs, pattern) {
  // Pair index: legs ranked front to back per side.
  const left = legs.filter(l => l.side >= 0);
  const right = legs.filter(l => l.side < 0);
  const pairs = Math.max(left.length, right.length, 1);
  const rank = (leg) => (leg.side < 0 ? right : left).indexOf(leg);
  let p = pattern;
  if (p === 'auto') p = legs.length <= 2 ? 'alternate' : legs.length === 4 ? 'walk' : legs.length >= 6 && legs.length % 2 === 0 ? 'tripod' : 'wave';
  const isFront = leg => rank(leg) < pairs / 2;
  const L = leg => leg.side >= 0;
  const table = {
    walk: { duty: 0.65, phase: leg => (isFront(leg) ? (L(leg) ? 0.25 : 0.75) : (L(leg) ? 0 : 0.5)) },
    trot: { duty: 0.5, phase: leg => ((isFront(leg) === L(leg)) ? 0 : 0.5) },
    pace: { duty: 0.5, phase: leg => (L(leg) ? 0 : 0.5) },
    bound: { duty: 0.4, phase: leg => (isFront(leg) ? 0.5 : 0) },
    gallop: { duty: 0.4, phase: leg => (isFront(leg) ? (L(leg) ? 0.5 : 0.6) : (L(leg) ? 0 : 0.1)) },
    alternate: { duty: legs.length <= 2 ? 0.6 : 0.5, phase: leg => ((rank(leg) + (L(leg) ? 0 : 1)) % 2) * 0.5 },
    wave: { duty: 0.75, phase: leg => ((pairs - 1 - rank(leg)) / pairs + (L(leg) ? 0 : 0.5)) % 1 }
  };
  table.tripod = table.alternate;
  const entry = table[p] || table.alternate;
  return { pattern: p, duty: entry.duty, phaseOf: entry.phase };
}

function gaitInputs(ctx, layer, t, out, w) {
  const legs = gaitLegs(ctx, layer);
  if (!legs.length) return;
  const { pattern, duty: defaultDuty, phaseOf } = gaitPhases(legs, layer.pattern);
  const duty = layer.duty ?? defaultDuty;
  const span = layer.end - layer.start;
  const period = span / layer.cycles;
  const local = t - layer.start;
  const meanLen = legs.reduce((s, l) => s + l.length, 0) / legs.length;
  const COMFORT = 0.94;
  // Each leg's geometry relative to its base: how far below, ahead and out
  // its ankle stands, and its length (base .. ankle).
  const geo = legs.map((leg) => {
    const chain = ctx.chains.get(leg.label);
    if (!chain || chain.ikJoints.length < 3) return null;
    const j = chain.ikJoints;
    const base = ctx.P[j[0]];
    const rel = ctx.P[j[j.length - 2]].clone().sub(base);
    let length = 0;
    for (let k = 1; k < j.length - 1; k += 1) length += ctx.P[j[k]].distanceTo(ctx.P[j[k - 1]]);
    return { label: leg.label, height: -rel.dot(ctx.U), along: rel.dot(ctx.F), side: rel.dot(ctx.L), length };
  }).filter(Boolean);
  // The longest stride every leg can take with the body lowered by at most a
  // quarter of its leg height. A sprawling spider leg reaches far less forward
  // than its length suggests - 35% of leg length put its targets out of reach.
  let maxStride = Infinity;
  let limitingLeg = null;
  for (const g of geo) {
    const room = (COMFORT * g.length) ** 2 - (0.75 * g.height) ** 2 - g.side * g.side;
    const s = room > 0 ? 2 * (Math.sqrt(room) - Math.abs(g.along)) : 0;
    if (s < maxStride) { maxStride = s; limitingLeg = g.label; }
  }
  maxStride = Math.max(maxStride, 0.05 * meanLen);
  const stride = layer.stride ?? Math.min(0.35 * meanLen, maxStride);
  if (layer.stride !== null && layer.stride !== undefined && layer.stride > maxStride * 1.05) {
    out.meta.warnings.add(`gait: stride ${layer.stride} is longer than ${limitingLeg} can reach (about ${maxStride.toFixed(3)} max) - its foot will miss the floor at the ends of the step.`);
  }
  const lift = layer.lift ?? 0.12 * meanLen;
  // Crouch: walking animals keep their legs flexed. A leg near full extension
  // is an IK singularity - tiny target moves need huge joint changes, which
  // showed up as a 24-28 degree foreleg pop at every touch-down on a horse
  // whose forelegs stand at 95% of their length. So lower the body until
  // every foot, at both ends of its stance, is within COMFORT of its reach.
  let drop = 0;
  for (const g of geo) {
    const d = Math.max(Math.abs(g.along + stride / 2), Math.abs(g.along - stride / 2));
    const room = (COMFORT * g.length) ** 2 - d * d - g.side * g.side;
    const needed = room > 0 ? g.height - Math.sqrt(room) : g.height * 0.25;
    if (needed > drop) drop = Math.min(needed, g.height * 0.25);
  }

  // Body speed while a foot is planted: it covers one stride per stance.
  const speed = stride / (duty * period);
  const travelled = layer.travel === 'forward' ? speed * local : 0;
  out.meta.gaits.push({ pattern, duty, stride, lift, period, speed: Math.round(speed * 1000) / 1000, bodyDrop: Math.round(drop * 1000) / 1000, legs: legs.map(l => l.label) });
  if (drop) add(out.root, null, 'up', -w * drop);

  for (const leg of legs) {
    const phase0 = layer.phases && layer.phases[leg.label] !== undefined ? layer.phases[leg.label] : phaseOf(leg);
    const u = (((local / period) - phase0) % 1 + 1) % 1; // 0..1 through this leg's cycle
    let fwd;
    let up;
    if (u < duty) {
      const s = u / duty;
      fwd = stride * (0.5 - s);
      up = 0;
    } else {
      const s = (u - duty) / (1 - duty);
      const eased = s * s * (3 - 2 * s);
      fwd = stride * (-0.5 + eased);
      up = lift * Math.sin(Math.PI * s);
    }
    add(out.ik, leg.label, 'forward', w * (fwd + travelled));
    add(out.ik, leg.label, 'up', w * up);
    if (!out.ik[leg.label]) out.ik[leg.label] = {};
  }
  if (layer.travel === 'forward') add(out.root, null, 'forward', w * travelled);
  // Bob: the body dips each time a group of feet lands - once per beat.
  const beats = pattern === 'walk' ? 4 : pattern === 'wave' ? Math.max(2, legs.length / 2) : 2;
  if (layer.bob) add(out.root, null, 'up', w * layer.bob * 0.5 * (1 - Math.cos(TWO_PI * beats * local / period)));
  if (layer.sway) add(out.root, null, 'roll', w * layer.sway * Math.sin(TWO_PI * local / period));
}

// ---- wave / oscillate / noise -------------------------------------------------

function waveInputs(ctx, layer, t, out, w) {
  const u = (t - layer.start) / (layer.end - layer.start);
  for (const label of layer.chains) {
    const chain = ctx.chains.get(label);
    if (!chain) { out.meta.warnings.add(`wave: unknown chain "${label}".`); continue; }
    const n = chain.joints.length;
    for (let i = 0; i < n; i += 1) {
      const along = n > 1 ? i / (n - 1) : 0;
      const fall = layer.falloff === 'even' ? 1 : layer.falloff === 'tip' ? 0.35 + 0.65 * along : 1 - 0.65 * along;
      // base_to_tip: crests travel away from the body (a wagging tail, a snake
      // pushing itself forward when its chain starts at the head).
      const travel = layer.direction === 'tip_to_base' ? -1 : 1;
      const angle = layer.amplitude * fall * Math.sin(TWO_PI * (layer.cycles * u - travel * layer.waves * along + layer.phase));
      add(out.targets, `${label}[${i}]`, layer.control, w * angle);
    }
  }
}

function shapeValue(shape, x) {
  const f = ((x % 1) + 1) % 1;
  if (shape === 'flap') {
    // Fast power stroke (35% of the cycle) then a slower recovery.
    return f < 0.35 ? Math.cos(Math.PI * f / 0.35) : -Math.cos(Math.PI * (f - 0.35) / 0.65);
  }
  if (shape === 'pulse') return Math.exp(-((f - 0.5) ** 2) / 0.01) * 2 - 1;
  return Math.sin(TWO_PI * f);
}

function oscillateInputs(ctx, layer, t, out, w) {
  const u = (t - layer.start) / (layer.end - layer.start);
  const value = layer.offset + layer.amplitude * shapeValue(layer.shape, layer.cycles * u + layer.phase);
  for (const target of layer.targets) {
    if (target === 'root' || layer.control.startsWith('root.')) {
      add(out.root, null, layer.control.replace(/^root\./, ''), w * value);
    } else {
      add(out.targets, target, layer.control, w * value);
    }
  }
}

function noiseInputs(ctx, layer, t, out, w) {
  const u = (t - layer.start) / (layer.end - layer.start);
  // Sum of whole-number harmonics with seeded phases: smooth, and periodic over
  // the layer, so a looping idle closes.
  let s = layer.seed * 9301 + 49297;
  const rand = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  for (const target of layer.targets) {
    for (const control of layer.controls) {
      let v = 0;
      for (const k of [1, 2, 3]) v += Math.sin(TWO_PI * (layer.speed * k * u + rand())) / k;
      add(out.targets, target, control, w * layer.amplitude * v / 1.83);
    }
  }
}

/**
 * Inputs (targets/root/ik) contributed by every non-spring layer at time t,
 * plus meta (gait summaries, warnings).
 */
export function layerInputsAt(ctx, layers, t, duration) {
  const out = { targets: {}, root: {}, ik: {}, meta: { gaits: [], warnings: new Set() } };
  for (const layer of layers) {
    layer.endOfClip = duration;
    const w = envelope(layer, t);
    if (layer.type === 'gait') {
      // A gait's IK chains stay solved outside its window (weight 0 = planted
      // at rest), or the legs would snap from planted to free.
      gaitInputs(ctx, layer, Math.min(layer.end, Math.max(layer.start, t)), out, w);
    } else if (!w) {
      continue;
    } else if (layer.type === 'wave') waveInputs(ctx, layer, t, out, w);
    else if (layer.type === 'oscillate') oscillateInputs(ctx, layer, t, out, w);
    else if (layer.type === 'noise') noiseInputs(ctx, layer, t, out, w);
  }
  return out;
}

/** Merge layer inputs onto key inputs (additive). */
export function mergeInputs(base, extra) {
  const targets = { ...(base.targets || {}) };
  for (const [k, controls] of Object.entries(extra.targets)) {
    targets[k] = { ...(targets[k] || {}) };
    for (const [c, v] of Object.entries(controls)) targets[k][c] = (targets[k][c] || 0) + v;
  }
  const root = { ...(base.root || {}) };
  for (const [c, v] of Object.entries(extra.root)) root[c] = (root[c] || 0) + v;
  const ik = { ...(base.ik || {}) };
  for (const [k, off] of Object.entries(extra.ik)) {
    ik[k] = { ...(ik[k] || {}) };
    for (const [c, v] of Object.entries(off)) ik[k][c] = (ik[k][c] || 0) + v;
  }
  return {
    targets,
    root: Object.keys(root).length ? root : null,
    ik: Object.keys(ik).length ? ik : null
  };
}
